// Node 2 — Search queries
// Emits ONE ITEM PER QUERY so the next HTTP node runs once per query.
// Month/year come from $now, so this keeps working without edits.
//
// Four queries are drawn from a rotating pool each day. Running the same four
// strings every day returns the same Google results all month, which is what
// made consecutive runs look identical. The pool size (12) and the step (5) are
// coprime, so the starting offset visits all 12 positions before repeating.

const QUERIES_PER_RUN = 4;
const ROTATION_STEP = 5;

const month = $now.toFormat('MMMM');
const year = $now.toFormat('yyyy');

const pool = [
  // the original four from the spec
  `trending products ${month} ${year} tiktok`,
  `viral products ${month} ${year} amazon`,
  `best selling dropshipping products ${month} ${year}`,
  `tiktok shop trending products this week`,
  // different sources, to get off the same listicles every day
  `tiktok made me buy it ${month} ${year}`,
  `amazon movers and shakers ${month} ${year}`,
  `viral gadgets ${month} ${year} reddit`,
  `winning products to sell online ${month} ${year}`,
  // category sweeps, which surface products the general queries never reach
  `trending kitchen gadgets ${month} ${year}`,
  `trending car accessories ${month} ${year}`,
  `viral home organization products ${month} ${year}`,
  `best selling beauty tools ${month} ${year}`,
];

// Day number since epoch, derived from the date string rather than a Luxon
// helper so the rotation is easy to reason about and to test.
const [y, m, d] = $now.toFormat('yyyy-MM-dd').split('-').map(Number);
const dayNumber = Math.floor(Date.UTC(y, m - 1, d) / 86400000);
const start = (dayNumber * ROTATION_STEP) % pool.length;

const queries = [];
for (let i = 0; i < QUERIES_PER_RUN; i++) {
  queries.push(pool[(start + i) % pool.length]);
}

return queries.map((query) => ({ json: { query } }));

// Node 4 — Flatten results
// Input: one item per Serper response (4 of them).
// Output: ONE item with a single text blob, capped at 12,000 characters.

const CHAR_CAP = 12000;

const lines = [];
const seen = new Set();

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const organic = Array.isArray(body.organic) ? body.organic : [];

  for (const result of organic) {
    const title = String(result.title ?? '').replace(/\s+/g, ' ').trim();
    const snippet = String(result.snippet ?? '').replace(/\s+/g, ' ').trim();
    const link = String(result.link ?? '').trim();
    if (!title && !snippet) continue;

    const key = (title + '|' + snippet).toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);

    lines.push(link ? `${title} — ${snippet} [${link}]` : `${title} — ${snippet}`);
  }
}

// Cap on a whole-result boundary so Claude never reads a half-truncated entry.
let blob = '';
let used = 0;
for (const line of lines) {
  if (used + line.length + 1 > CHAR_CAP) break;
  blob += line + '\n';
  used += line.length + 1;
}

return [{ json: { blob: blob.trim(), resultCount: lines.length, blobChars: blob.trim().length } }];

// Node 6 — Parse, filter, and drop anything already seen
//
// Reads Claude's reply, strips fences, parses JSON, drops score < 6, sorts desc,
// then removes every product this workflow has already reported on a previous
// run. Emits ONE ITEM PER NEW PRODUCT (rejects included — those are the training
// data), each carrying the same `hasNew` flag and the same finished `message`.
//
// Cross-run memory lives in $getWorkflowStaticData('global'), which n8n persists
// on the workflow record between executions. Two things to know about it:
//   - it is only saved after a SUCCESSFUL execution, so a failed Telegram send
//     leaves products unseen and they get reported again next run, which is the
//     safe direction to fail in;
//   - n8n does not persist it for MANUAL test runs, only scheduled/production
//     ones. Testing by hand will therefore show no de-duplication. That is
//     expected, not a bug.

const SCORE_THRESHOLD = 6;
const TOP_N = 5;
const RETENTION_DAYS = 90;
const MAX_MEMORY = 500;

const date = $now.toFormat('yyyy-MM-dd');

const incoming = $input.first().json;
const body = incoming.body ?? incoming;

let text = '';
try {
  text = body.content[0].text;
} catch (e) {
  text = typeof body === 'string' ? body : JSON.stringify(body);
}

function stripFences(s) {
  return String(s || '')
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/, '')
    .trim();
}

function sliceArray(s) {
  const start = s.indexOf('[');
  const end = s.lastIndexOf(']');
  if (start === -1 || end === -1 || end < start) return null;
  return s.slice(start, end + 1);
}

// Telegram legacy Markdown does not reliably honour backslash escapes, so the
// safe move is to remove the characters that break a message rather than escape
// them. Anything with _ * ` [ ] in it would otherwise fail to send.
function clean(v) {
  return String(v ?? '')
    .replace(/[_*`\[\]]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function num(v) {
  const n = Number(v);
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
}

function money(v) {
  const n = num(v);
  return n === null ? '?' : n;
}

// --- product identity -------------------------------------------------------
// Case, punctuation and word order are all noise: "LED Strip Lights",
// "led strip lights" and "Strip Lights LED" are the same product. Compare the
// set of words instead of the string.
function tokenize(name) {
  return new Set(
    String(name ?? '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, ' ')
      .split(' ')
      .filter((w) => w.length > 1)
  );
}

function isSubset(a, b) {
  for (const x of a) if (!b.has(x)) return false;
  return true;
}

function sameProduct(a, b) {
  if (a.size === 0 || b.size === 0) return false;
  if (a.size === b.size && isSubset(a, b)) return true;
  // "cooling neck fan" and "neck fan" are the same thing. Only allow this when
  // both names have at least two words, or a one-word name would swallow half
  // the catalogue.
  if (a.size >= 2 && b.size >= 2 && (isSubset(a, b) || isSubset(b, a))) return true;
  return false;
}

function emit(json) {
  return [{ json: { date, hasNew: false, passed: false, error: false, ...json } }];
}

// --- parse ------------------------------------------------------------------
let parsed;
try {
  const cleaned = stripFences(text);
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    const arr = sliceArray(cleaned);
    if (!arr) throw e;
    parsed = JSON.parse(arr);
  }
  if (!Array.isArray(parsed)) throw new Error('Expected a JSON array');
} catch (err) {
  // Never fail the workflow on a bad response — report it downstream instead.
  const raw = String(text).slice(0, 500);
  return emit({
    error: true,
    raw,
    emptyReason: 'parse_error',
    message:
      'Scan complete. Claude response could not be parsed. Raw: ' +
      clean(raw).slice(0, 400),
    product: '(parse error)',
    score: 0,
    est_retail_usd: null,
    est_landed_usd: null,
    reason: 'Claude response could not be parsed as JSON',
    risk: String(err.message).slice(0, 200),
  });
}

const scored = parsed
  .map((p) => {
    const rawScore = Number(p.score);
    const score = Number.isFinite(rawScore)
      ? Math.min(10, Math.max(0, Math.round(rawScore)))
      : 0;
    return {
      date,
      product: String(p.product ?? '').replace(/\s+/g, ' ').trim(),
      score,
      est_retail_usd: num(p.est_retail_usd),
      est_landed_usd: num(p.est_landed_usd),
      reason: String(p.reason ?? '').replace(/\s+/g, ' ').trim(),
      risk: String(p.risk ?? '').replace(/\s+/g, ' ').trim(),
      source_url: p.source_url ?? null,
    };
  })
  .filter((p) => p.product.length > 0);

scored.sort((a, b) => b.score - a.score);

if (scored.length === 0) {
  return emit({
    emptyReason: 'nothing_extracted',
    message: 'Scan complete. Nothing cleared the bar today.',
    product: '(no products extracted)',
    score: 0,
    est_retail_usd: null,
    est_landed_usd: null,
    reason: 'Search results contained no shippable physical products',
    risk: '',
  });
}

// --- drop anything already reported on a previous run -----------------------
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.seen)) store.seen = [];

const cutoff = new Date(Date.now() - RETENTION_DAYS * 86400000)
  .toISOString()
  .slice(0, 10);
store.seen = store.seen.filter((e) => e && e.p && String(e.d ?? '') >= cutoff);

const memory = store.seen.map((e) => ({ entry: e, tok: tokenize(e.p) }));

const fresh = [];
for (const p of scored) {
  const tok = tokenize(p.product);
  const hit = memory.find((m) => sameProduct(tok, m.tok));
  if (hit) {
    hit.entry.n = (hit.entry.n || 1) + 1;
    hit.entry.last = date;
    continue;
  }
  fresh.push(p);
  const entry = { p: p.product, s: p.score, d: date, n: 1, last: date };
  store.seen.push(entry);
  memory.push({ entry, tok });
}

if (store.seen.length > MAX_MEMORY) {
  store.seen = store.seen.slice(store.seen.length - MAX_MEMORY);
}

if (fresh.length === 0) {
  return emit({
    emptyReason: 'all_repeats',
    message:
      `Scan complete. ${scored.length} product` +
      (scored.length === 1 ? '' : 's') +
      ' scored, all already reported. Nothing new today.',
    product: '(no new products)',
    score: 0,
    est_retail_usd: null,
    est_landed_usd: null,
    reason: 'Every product scored this run had been seen before',
    risk: '',
  });
}

// --- build the message ------------------------------------------------------
const survivors = fresh.filter((p) => p.score >= SCORE_THRESHOLD);

let message;
if (survivors.length === 0) {
  message = 'Scan complete. Nothing cleared the bar today.';
} else {
  const top = survivors.slice(0, TOP_N);
  message = `*Product scan — ${date}*\n\n`;
  top.forEach((p, i) => {
    message += `*${i + 1}. ${clean(p.product)} — ${p.score}/10*\n`;
    message += `${clean(p.reason)}\n`;
    message += `Retail ~$${money(p.est_retail_usd)} | Landed ~$${money(p.est_landed_usd)}\n`;
    message += `Risk: ${clean(p.risk)}\n\n`;
  });
  message += '_Prices are estimates. Verify on AliExpress before buying._';
}

return fresh.map((p) => ({
  json: {
    ...p,
    error: false,
    hasNew: true,
    passed: p.score >= SCORE_THRESHOLD,
    emptyReason: null,
    message,
  },
}));
